(() => {
  'use strict';
  const D = window.POLITY;
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function emphasize(text){let s=esc(text);s=s.replace(/\b(?:\d{1,2}\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+)?(?:17|18|19|20)\d{2}\b/g,'<strong class="key-fact">$&</strong>');['B. R. Ambedkar','B.R. Ambedkar','Dr. B. R. Ambedkar','B. N. Rau','Dr. Rajendra Prasad','Jawaharlal Nehru','Sachchidananda Sinha','Prem Behari Narain Raizada','Swarna Singh','Morley','Minto','Montagu','Chelmsford'].forEach(n=>{s=s.replace(new RegExp(n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),'<strong class="key-fact">$&</strong>')});return s;}
  function clozeHTML(text){const pattern=/\b(?:\d{1,2}\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+)?(?:17|18|19|20)\d{2}\b|\bArticles?\s+\d+[A-Z]?(?:\s*(?:and|to|,|&|–|-)\s*\d+[A-Z]?)?|B\.?\s?R\.?\s?Ambedkar|B\.?\s?N\.?\s?Rau|Dr\.?\s+Rajendra Prasad|Jawaharlal Nehru|Sachchidananda Sinha|Prem Behari Narain Raizada|Swarna Singh|\b[A-Z][a-z]{2,}\s+(?:[A-Z][a-z]{2,}\s?){1,2}/g;let html='',last=0;for(const m of text.matchAll(pattern)){html+=esc(text.slice(last,m.index))+`<button type="button" class="cloze-blank" data-cloze-answer="${esc(m[0])}">______</button>`;last=m.index+m[0].length}return html+esc(text.slice(last))||esc(text)}
  const storeKey='polityprep-v2',legacyKey='polityprep-v1';
  const initial={completed:[],bookmarks:[],answers:[],results:[],lastStudied:null,theme:'light',totalCorrect:0,totalAttempted:0,streakDays:[],freezeDays:[],freezeUsed:false,srs:{},personalCards:[],mnemonics:{},xp:0,planner:{},fontScale:1};
  let state;
  try{const current=localStorage.getItem(storeKey),legacy=localStorage.getItem(legacyKey);state={...initial,...JSON.parse(current||legacy||'{}')};state.srs||={};state.freezeDays||=[];state.personalCards||=[];state.mnemonics||={};state.planner||={};if(!current&&legacy)localStorage.setItem(storeKey,JSON.stringify(state))}catch{state={...initial}}
  const save=()=>localStorage.setItem(storeKey,JSON.stringify(state));
  const topic=id=>D.modules.find(x=>x.id===id);
  function srsCatalog(){const items=[];D.flashcards.forEach((f,i)=>items.push({kind:'flashcard',key:`flash:${i}`,prompt:f[0],answer:f[1],topic:'Revision'}));D.modules.forEach(m=>(m.facts||[]).forEach((f,i)=>items.push({kind:'fact',key:`fact:${m.id}:${i}`,prompt:f[0],answer:f[1],topic:m.title})));[...D.questions,...D.pyqs].forEach((q,i)=>items.push({kind:'question',key:`question:${q.id||i}`,question:q,topic:topic(q.topic)?.title||q.topic}));state.personalCards.forEach((f,i)=>items.push({kind:'personal',key:`personal:${f.id||i}`,prompt:f.front,answer:f.back,topic:'My cards'}));return items;}
  function nextIntervalLabel(id,rating){if(rating==='again')return '10 min';const r=window.POLITY_SRS.record(state,id);let days=rating==='hard'?Math.max(1,Math.round((r.interval||1)*1.2)):r.reps===0?(rating==='easy'?4:1):r.reps===1?(rating==='easy'?8:3):Math.max(1,Math.round(r.interval*r.ease*(rating==='easy'?1.3:1)));return days+' day'+(days===1?'':'s')}
  function dueItems(){return srsCatalog().filter(item=>window.POLITY_SRS.due(state,item.key));}
  function startSprint(){const due=dueItems(),buckets=['flashcard','question','fact','personal'].map(kind=>due.filter(x=>x.kind===kind));sprintItems=[];while(sprintItems.length<10&&buckets.some(b=>b.length)){for(const b of buckets){if(b.length&&sprintItems.length<10)sprintItems.push(b.shift())}}sprintIndex=0;sprintXPstart=state.xp||0;sprintRevealed=false;sprintChoice=null;currentPage='sprint';$('#page-label').textContent='Review sprint';quiz=null;markStudy();render();}
  const progressPct=()=>Math.round(state.completed.length/D.modules.filter(m=>m.category!=='Revision').length*100);
  const iconList=['◈','⌘','⌖','⚖','⇢','✳','♙','▥','§','♜','♧','◉','⇆','⚠','▦','⌂'];
  const days=['M','T','W','T','F','S','S'];
  function dateKey(d){const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`}
  function activeDays(){return new Set([...(state.streakDays||[]),...(state.freezeDays||[])])}
  function currentStreak(){const active=activeDays(),cursor=new Date();if(!active.has(dateKey(cursor)))cursor.setDate(cursor.getDate()-1);let count=0;while(active.has(dateKey(cursor))){count++;cursor.setDate(cursor.getDate()-1)}return count}
  function markStudy(){const today=dateKey(new Date());state.streakDays||=[];state.freezeDays||=[];const prior=[...state.streakDays].sort().at(-1);if(prior){const gap=Math.round((Date.parse(today+'T00:00:00Z')-Date.parse(prior+'T00:00:00Z'))/86400000);if(gap===2){const missed=dateKey(new Date(Date.parse(today+'T00:00:00Z')-86400000));if(!state.freezeUsed&&!state.freezeDays.includes(missed)){state.freezeDays.push(missed);state.freezeUsed=true}}}state.lastStudied=today;if(!state.streakDays.includes(today))state.streakDays.push(today);save();renderSide();}
  function renderSide(){const streak=$('#streak');if(streak)streak.textContent=currentStreak();const dots=$('#streak-dots');if(dots){const active=activeDays();dots.innerHTML=days.map((_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return `<i class="${active.has(dateKey(d))?'done':''} ${i===6&&active.has(dateKey(d))?'today':''}"></i>`}).join('')}document.body.classList.toggle('dark',state.theme==='dark');$('#theme-label').textContent=state.theme==='dark'?'Light':'Dark';document.documentElement.style.setProperty('--text-scale',Math.max(1,Math.min(1.2,state.fontScale||1)));}
  let currentPage='dashboard',currentModule=null,filter='All',quiz=null,flashIndex=0,flashBack=false,pyqExamFilter='All exams',pyqTopicFilter='All topics',lessonMode='read',sprintItems=[],sprintIndex=0,sprintRevealed=false,sprintChoice=null,trapDuel=null;
  const openPyqs=new Set(),openCountries=new Set(),revealedFacts=new Set(),clozeFacts=new Set();
  function go(page){currentPage=page;currentModule=null;quiz=null;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const names={dashboard:'Overview',learn:'Learn',practice:'Practice',pyqs:'Previous-year questions',borrowed:'Borrowed features',revise:'Revise',progress:'My progress',sources:'Sources & method',sprint:'Review sprint',map:'Knowledge map',planner:'Exam planner',games:'Active recall games',trap:'Trap Duel', 'country-game':'Country match'};$('#page-label').textContent=names[page]||'Overview';$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'});}
  function header(eyebrow,title,subtitle,right=''){return `<div class="welcome-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div>${right}</div>`;}
  function moduleCard(m){const pct=state.completed.includes(m.id)?100:0;return `<button class="module-card" data-module="${m.id}"><div class="module-card-top"><span class="module-icon">${m.icon}</span><span class="priority ${m.priority}">${m.priority==='very-high'?'VERY HIGH':m.priority.toUpperCase()}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.summary)}</p><div class="module-card-bottom"><span>${esc(m.category)} · ${m.duration}</span><span>${pct? 'Completed ✓':'Open →'}</span></div></button>`;}
  function chapterCheckCard(m){return `<section class="chapter-test-card"><div><h3>5-question chapter check</h3><p>Finish with a short quiz, see explanations, and save missed concepts to your revision list.</p></div><button class="button-green" data-chapter-test="${m.id}">Take chapter test →</button></section>`;}
  function dashboard(){let correct=state.totalCorrect||0,attempted=state.totalAttempted||0;let m=topic(state.lastModule)||D.modules.find(x=>!state.completed.includes(x.id)&&x.category!=='Revision')||D.modules[0];let todays=new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'}),due=dueItems().length,todayXP=state.xpByDay?.[dateKey(new Date())]||0,goalPct=Math.min(100,Math.round(todayXP/50*100));return `${header('YOUR STUDY SPACE','Build a little polity, every day.','A clear path from first principles to exam-ready recall.',`<div class="date-label"><strong>${todays}</strong>One focused session is enough to begin.</div>`)}<section class="hero-card"><div class="hero-copy"><div class="eyebrow">PICK UP WHERE YOU LEFT OFF</div><h2>${esc(m.title)}</h2><p>${esc(m.summary)}</p><button class="button-primary" data-module="${m.id}">${state.completed.includes(m.id)?'Review this lesson':'Continue lesson'} <span>→</span></button></div><div class="hero-progress"><div class="ring" style="--progress:${progressPct()*3.6}deg"><strong>${progressPct()}%</strong></div><small>curriculum covered</small></div></section><section class="queue-panel"><div class="daily-goal" style="--goal:${goalPct}%"><strong>${todayXP}/50 XP</strong></div><div><div class="eyebrow">SPACED REVIEW</div><h2>Today's queue <span>${due}</span></h2><p>${due?`About ${Math.max(1,Math.ceil(Math.min(due,10)*.5))} minutes · due cards, facts and questions`:'You are caught up. Try a practice set any time.'}</p></div><button class="button-green" id="start-sprint" ${due?'':'disabled'}>Start 5-minute sprint →</button></section><div class="stat-grid"><div class="stat-card"><div class="stat-top">Lessons completed <span class="stat-icon">✓</span></div><div class="stat-value">${state.completed.length}<span style="font-size:0.75rem;color:var(--muted);font-weight:500"> / ${D.modules.filter(x=>x.category!=='Revision').length}</span></div><div class="stat-note">Keep your own pace</div></div><div class="stat-card"><div class="stat-top">Questions attempted <span class="stat-icon">◉</span></div><div class="stat-value">${attempted}</div><div class="stat-note">${attempted?`${Math.round(correct/attempted*100)}% accuracy overall`:'Start a short practice set'}</div></div><div class="stat-card"><div class="stat-top">Cards to recall <span class="stat-icon">↻</span></div><div class="stat-value">${D.flashcards.length}</div><div class="stat-note">Quick daily revision</div></div><div class="stat-card"><div class="stat-top">Study streak <span class="stat-icon">✦</span></div><div class="stat-value">${currentStreak()}<span style="font-size:0.75rem;color:var(--muted);font-weight:500"> days</span></div><div class="stat-note">A session today keeps it going</div></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h3>Continue learning</h3><button class="text-link" data-go="learn">All modules →</button></div><div class="continue-card"><div class="continue-art">${m.icon}</div><div class="continue-info"><small>${esc(m.category)} · ${m.duration}</small><strong>${esc(m.title)}</strong><div class="mini-progress"><i style="width:${state.completed.includes(m.id)?100:12}%"></i></div></div><div class="continue-meta">${state.completed.includes(m.id)?'Review':'Next up'}<button data-module="${m.id}">Open →</button></div></div><div class="section-row"><div><h3>Today's short session</h3><p>Learn a little, then check recall.</p></div></div><div class="quick-grid"><button class="quick-card" data-module="history"><span class="quick-symbol">▤</span><strong>One new lesson</strong><small>Start with the foundations</small></button><button class="quick-card" data-go="revise"><span class="quick-symbol">↻</span><strong>Recall cards</strong><small>${D.flashcards.length} cards ready</small></button><button class="quick-card" data-quiz="mixed"><span class="quick-symbol">◉</span><strong>30 questions</strong><small>Mixed practice, instant feedback</small></button><button class="quick-card" data-go="practice"><span class="quick-symbol">◷</span><strong>Mini test</strong><small>Timed exam-mode option</small></button></div></section><section class="panel"><div class="panel-heading"><h3>Study priorities</h3><button class="text-link" data-go="learn">See all</button></div><p style="font-size:0.75rem;color:var(--muted);line-height:1.5;margin:0 0 11px">Editorial priorities based on syllabus breadth and foundational value—not measured PYQ counts.</p><div class="weak-row"><div><strong>Fundamental Rights</strong><small>Articles 12–35 · high recall value</small></div><span class="priority very-high">CORE</span></div><div class="weak-row"><div><strong>Parliament</strong><small>House roles · Bill procedure</small></div><span class="priority very-high">CORE</span></div><div class="weak-row"><div><strong>Emergency provisions</strong><small>Articles 352 · 356 · 360</small></div><span class="priority high">REVISE</span></div><div class="weak-row"><div><strong>Articles & amendments</strong><small>Quick recall is powerful</small></div><span class="priority high">REVISE</span></div><div style="margin-top:13px"><button class="button-green" data-go="revise">Open quick revision →</button></div></section></div><div class="section-row"><div><h3>Your topic progress</h3><p>Progress stays on this device.</p></div><button class="text-link" data-go="progress">View progress →</button></div><div class="topic-progress-list">${D.modules.filter(x=>x.priority==='very-high').slice(0,6).map(m=>`<div class="topic-progress"><div class="topic-progress-head"><span>${esc(m.title)}</span><span>${state.completed.includes(m.id)?'100%':'0%'}</span></div><div class="mini-progress"><i style="width:${state.completed.includes(m.id)?100:0}%"></i></div><small>${esc(m.category)}</small></div>`).join('')}</div>`;}
  function rateSprint(rating){const item=sprintItems[sprintIndex];if(!item)return;window.POLITY_SRS.schedule(state,item.key,rating);if(rating==='good'||rating==='easy')awardXP(10);save();sprintIndex++;sprintRevealed=false;sprintChoice=null;render();}
  function sprintPage(){if(!sprintItems.length)return `${header('SPACED REVIEW','Nothing is due right now.','New cards and questions will enter the queue automatically')}<section class="queue-panel"><div><h2>Queue clear ✓</h2><p>Come back when more items are due.</p></div><button class="button-green" data-go="dashboard">Back to overview</button></section>`;if(sprintIndex>=sprintItems.length)return `${header('SPRINT COMPLETE','Good recall. Keep the intervals working.','You reviewed '+sprintItems.length+' due items and earned '+((state.xp||0)-sprintXPstart)+' recall XP.')}<section class="quiz-panel"><div class="result-score">+${sprintItems.length*10}<span> XP</span></div><p>Points are awarded for recalling and rating your memory.</p><button class="button-green" data-go="dashboard">Finish sprint</button></section>`;const x=sprintItems[sprintIndex];let body='';if(x.kind==='question'){const q=x.question;body=`<div class="quiz-topic">${esc(x.topic)} · ${esc(q.exam||'Original practice')}</div><h2 class="quiz-question">${esc(q.q)}</h2><div class="option-list">${q.options.map((o,i)=>`<button class="option ${sprintChoice===i?(i===q.answer?'correct':'wrong'):''}" data-sprint-option="${i}" ${sprintChoice!==null?'disabled':''}>${esc(o)}</button>`).join('')}</div>${sprintChoice!==null?`<div class="answer-note"><strong>Answer: ${esc(q.options[q.answer])}</strong><p>${esc(q.explanation)}</p></div>`:''}`;}else{body=`<div class="eyebrow">${esc(x.topic)} · ${x.kind==='fact'?'FACT RECALL':'FLASHCARD'}</div><h2 class="quiz-question">${esc(x.prompt)}</h2>${sprintRevealed?`<div class="answer-note good">${esc(x.answer)}</div>`:`<button class="button-green" id="sprint-reveal">Reveal answer</button>`}`;}const canRate=x.kind==='question'?sprintChoice!==null:sprintRevealed;return `${header('5-MINUTE SPRINT','Item '+(sprintIndex+1)+' of '+sprintItems.length,'Recall first. Rate how well it came back to set the next review date.')}<section class="quiz-panel"><div class="quiz-progress"><i style="width:${Math.round(sprintIndex/sprintItems.length*100)}%"></i></div>${body}${canRate?`<div class="srs-ratings"><p>When should you see this again?</p><button data-srs-rate="again">Again <small>10 min</small></button><button data-srs-rate="hard">Hard <small>${nextIntervalLabel(x.key,'hard')}</small></button><button data-srs-rate="good">Good <small>${nextIntervalLabel(x.key,'good')}</small></button><button data-srs-rate="easy">Easy <small>${nextIntervalLabel(x.key,'easy')}</small></button></div>`:''}<button class="text-link" data-go="dashboard">Leave sprint</button></section>`;}
  function learn(){const cats=['All',...new Set(D.modules.map(m=>m.category))];let mods=D.modules.filter(m=>filter==='All'||m.category===filter);return `${header('CURRICULUM','Learn the whole system, one concept at a time.','28 focused modules. Start at the beginning or jump straight to a topic you need.') }<div class="filter-row">${cats.map(c=>`<button class="filter-chip ${filter===c?'selected':''}" data-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="module-grid">${mods.map(moduleCard).join('')}</div>`;}
  function modulePage(m){const idx=D.modules.indexOf(m),visible=D.modules.filter(x=>x.category!=='Revision'),n=visible.findIndex(x=>x.id===m.id);let prev=n>0?visible[n-1]:null,next=n>=0&&n<visible.length-1?visible[n+1]:null;let facts=(m.facts||[]).map(([a,b],i)=>{const key=`fact:${m.id}:${i}`,shown=revealedFacts.has(key),recall=lessonMode==='recall';return `<div class="fact-card recall-fact"><small>${emphasize(a)}</small>${!recall||shown?`<p>${clozeFacts.has(key)?clozeHTML(b):emphasize(b)}</p>`:`<button class="button-secondary" data-reveal-fact="${key}">Recall, then reveal</button>`}${recall&&shown?`<button class="text-link" data-cloze-toggle="${key}">${clozeFacts.has(key)?'Show full fact':'Try cloze blanks'}</button><div class="srs-ratings compact"><button data-rate-fact="${key}" data-rating="again">Again <small>${nextIntervalLabel(key,'again')}</small></button><button data-rate-fact="${key}" data-rating="hard">Hard <small>${nextIntervalLabel(key,'hard')}</small></button><button data-rate-fact="${key}" data-rating="good">Good <small>${nextIntervalLabel(key,'good')}</small></button><button data-rate-fact="${key}" data-rating="easy">Easy <small>${nextIntervalLabel(key,'easy')}</small></button></div>`:''}<label class="mnemonic-label">My mnemonic<input id="memo-${m.id}-${i}" data-mnemonic="${key}" value="${esc(state.mnemonics[key]||'')}" placeholder="Add a personal memory cue"></label></div>`}).join('');let timeline=m.timeline?`<section class="lesson-section"><h3>Timeline</h3><div class="timeline">${m.timeline.map(([d,t])=>`<div class="timeline-item"><strong>${emphasize(d)}</strong><p>${emphasize(t)}</p></div>`).join('')}</div></section>`:'';let actions=`<div class="lesson-actions"><button class="button-secondary" ${prev?`data-module="${prev.id}"`:'disabled'}>${prev?'← Previous module':'Start of curriculum'}</button><button class="button-green" id="mark-complete">${state.completed.includes(m.id)?'Completed ✓':'Mark complete'} · Next →</button></div>`;return `${header('LEARN / '+m.category.toUpperCase(),m.title,m.summary)}<div class="lesson-layout"><aside class="lesson-sidebar">${visible.map(x=>`<button class="lesson-nav-item ${x.id===m.id?'active':''}" data-module="${x.id}">${esc(x.title)}</button>`).join('')}</aside><article class="lesson-body"><div class="lesson-top"><div><div class="eyebrow">${m.priority.replace('-',' ')} PRIORITY · ${m.duration}</div><h2>${esc(m.title)}</h2></div><div class="lesson-tools"><button class="button-secondary" data-speak-lesson>Read aloud</button><button class="save-button ${state.bookmarks.includes(m.id)?'saved':''}" id="bookmark">${state.bookmarks.includes(m.id)?'★ Saved':'☆ Save'}</button></div></div><div class="lesson-summary"><strong>Remember:</strong> ${emphasize(m.remember)}</div><div class="mode-toggle"><button class="button-secondary ${lessonMode==='read'?'selected':''}" data-lesson-mode="read">Read mode</button><button class="button-secondary ${lessonMode==='recall'?'selected':''}" data-lesson-mode="recall">Recall mode</button><button class="button-secondary" data-trap-duel="${m.id}">Trap Duel · 30 sec</button></div><section class="lesson-section"><h3>${lessonMode==='recall'?'Recall each point':'What you need to know'}</h3><div class="fact-grid">${facts}</div></section>${timeline}<section class="lesson-section"><h3>Common trap</h3><div class="trap-box">${emphasize(m.trap)}</div></section>${m.id==='rights'?`<section class="lesson-section"><h3>Writ matching · quick recall</h3><table class="comparison-table"><thead><tr><th>Situation</th><th>Writ</th></tr></thead><tbody><tr><td>Detained person is not brought before court</td><td>Habeas corpus</td></tr><tr><td>Public authority refuses a legal duty</td><td>Mandamus</td></tr><tr><td>Lower court is proceeding beyond jurisdiction</td><td>Prohibition</td></tr><tr><td>Quash an order made without jurisdiction</td><td>Certiorari</td></tr><tr><td>Challenge unlawful claim to public office</td><td>Quo warranto</td></tr></tbody></table></section>`:''}${m.id==='parliament'||m.id==='state-legislature'?`<section class="lesson-section"><h3>Bill journey</h3><div class="timeline"><div class="timeline-item"><strong>Introduce</strong><p>Ordinary Bill may start in either House; Money Bill starts only in Lok Sabha / Assembly.</p></div><div class="timeline-item"><strong>Consider & pass</strong><p>Each House follows its stages. Money Bill has a limited recommendation role in the second House.</p></div><div class="timeline-item"><strong>Assent</strong><p>President for Parliament Bills; Governor for State Bills, with constitutional options including reservation in specified cases.</p></div></div></section>`:''}${chapterCheckCard(m)}${actions}</article></div>`;}
  function practice(){return `${header('PRACTICE','Recall it under a little pressure.','Original exam-style questions across RRB, SSC and PSC topics. Instant explanations; no fabricated PYQs.')}<section class="panel" style="margin-top:18px"><div class="panel-heading"><h3>Choose a practice set</h3><span class="priority high">${D.questions.length} QUESTIONS</span></div><div class="module-grid">${[{n:'Topic sprint',desc:'10 questions · focused review',len:10,kind:'topic'},{n:'Chapter test',desc:'20 questions · build confidence',len:20,kind:'chapter'},{n:'Mixed test',desc:'30 questions · switch topics',len:30,kind:'mixed'},{n:'Polity mock',desc:`${D.questions.length} questions · full question bank`,len:D.questions.length,kind:'mock'}].map((x,i)=>`<button class="module-card" data-quiz="${x.kind}"><div class="module-card-top"><span class="module-icon">${['◉','▤','⇄','◷'][i]}</span><span class="priority ${i<2?'high':'medium'}">${x.len} Q</span></div><h3>${x.n}</h3><p>${x.desc}</p><div class="module-card-bottom"><span>${i===3?'Untimed':'Untimed by default'}</span><span>Start →</span></div></button>`).join('')}</div><div class="panel-heading" style="margin-top:15px"><h3>Timed exam mode</h3><span class="priority medium">15 MIN · −0.25 / WRONG</span></div><div class="continue-card"><div class="continue-art">◷</div><div class="continue-info"><small>30 questions · mixed topics · countdown timer</small><strong>Exam conditions, with negative marking</strong></div><button class="button-green" data-quiz-exam="mixed">Start timed test →</button></div><div class="source-note">Topic sprint samples the question bank; other sets draw a mixed set. This question bank is original practice content, not verbatim PYQs.</div></section><section class="panel" style="margin-top:14px"><div class="panel-heading"><h3>Recent results</h3></div>${state.results.length?state.results.slice(-5).reverse().map(r=>`<div class="weak-row"><div><strong>${esc(r.name)}</strong><small>${new Date(r.date).toLocaleDateString()}</small></div><span class="priority ${r.pct>=70?'high':'medium'}">${r.score}/${r.total} · ${r.pct}%</span></div>`).join(''):`<div class="empty-state">Your results will show here after your first test.</div>`}</section>`;}
  function startQuiz(kind,examMode=false,chapterId=null){let qs=[],quizKind=kind,count; if(chapterId){const m=topic(chapterId);quizKind='chapter-check';const allQ=[...D.questions,...(D.pyqs||[])].map(q=>({...q,options:[...q.options]}));const direct=allQ.filter(q=>q.topic===chapterId);const related=allQ.filter(q=>topic(q.topic)?.category===m?.category&&!direct.some(d=>d.id===q.id)).sort(()=>Math.random()-.5);const filler=allQ.filter(q=>!direct.some(d=>d.id===q.id)&&!related.some(r=>r.id===q.id)).sort(()=>Math.random()-.5);qs=[...direct,...related,...filler].slice(0,5);count=qs.length;}else{count=kind==='topic'?10:kind==='chapter'?20:kind==='mixed'?30:D.questions.length;const pool=[...D.questions].map(q=>({...q,options:[...q.options]}));if(examMode){const misses=state.answers.reduce((a,x)=>{if(!x.correct)a[x.topic]=(a[x.topic]||0)+1;return a},{});pool.sort((a,b)=>((misses[b.topic]||0)+(topic(b.topic)?.priority==='very-high'?2:0)+Math.random())-((misses[a.topic]||0)+(topic(a.topic)?.priority==='very-high'?2:0)+Math.random()))}else pool.sort(()=>Math.random()-.5);qs=pool.slice(0,count);}quiz={kind:quizKind,chapterId,chapterTitle:chapterId?topic(chapterId)?.title:null,examMode,qs,index:0,selected:null,answered:false,correct:0,wrong:0,skipped:0,start:Date.now(),seconds:examMode?900:null,clock:null};markStudy();currentPage='quiz';$('#page-label').textContent=examMode?'Exam mode':'Practice';render();if(examMode)quiz.clock=setInterval(()=>{if(!quiz)return;quiz.seconds--;const t=$('#quiz-clock');if(t)t.textContent=fmtTime(quiz.seconds);if(quiz.seconds<=0)finishQuiz()},1000);}
  const fmtTime=s=>`${Math.floor(Math.max(s,0)/60).toString().padStart(2,'0')}:${(Math.max(s,0)%60).toString().padStart(2,'0')}`;
  function quizPage(){if(!quiz)return practice();let q=quiz.qs[quiz.index];let pct=Math.round(quiz.index/quiz.qs.length*100);return `${header(quiz.examMode?'EXAM MODE':'PRACTICE SET',quiz.examMode?'Timed polity test':quiz.chapterTitle?quiz.chapterTitle+' chapter check':`${quiz.kind[0].toUpperCase()+quiz.kind.slice(1)} practice`,'Answer from memory. Read the explanation, especially when your first instinct misses.')}<section class="quiz-panel"><div class="quiz-top"><span>Question ${quiz.index+1} of ${quiz.qs.length} · ${esc(topic(q.topic)?.title||q.topic)}</span><span>${quiz.examMode?`Time left <strong id="quiz-clock">${fmtTime(quiz.seconds)}</strong> · −0.25 wrong`:'Instant feedback'}</span></div><div class="quiz-progress"><i style="width:${pct}%"></i></div><div class="quiz-topic">${esc(q.exam||'Polity practice')} · ${esc(q.difficulty||q.status||'Exam-style')}</div><h2 class="quiz-question">${esc(q.q)}</h2><div class="option-list">${q.options.map((o,i)=>{let cls='';if(quiz.answered&&i===q.answer)cls='correct';else if(quiz.answered&&i===quiz.selected)cls='wrong';return `<button class="option ${cls}" data-option="${i}" ${quiz.answered?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span>${esc(o)}</button>`}).join('')}</div>${quiz.answered?`<div class="answer-note ${quiz.selected===q.answer?'good':'bad'}"><strong>${quiz.selected===q.answer?'Correct.':'Not quite.'}</strong> ${esc(q.explanation)} <br><small>Topic: ${esc(topic(q.topic)?.title||q.topic)}</small>${!q._correct&&topic(q.topic)?.trap?`<p><strong>Related trap:</strong> ${esc(topic(q.topic).trap)}</p>`:''}</div><div class="quiz-confidence"><strong>How sure were you?</strong>${[['sure','Sure'],['unsure','Unsure'],['guess','Guess']].map(([v,l])=>`<button class="${quiz.confidence===v?'selected':''}" data-confidence="${v}">${l}</button>`).join('')}</div>`:''}<div class="quiz-bottom"><small>${quiz.index+1} / ${quiz.qs.length} · ${quiz.correct} correct so far</small>${quiz.answered?`<button class="button-green" id="quiz-next" ${quiz.answered&&!quiz.confidence?'disabled':''}>${quiz.index===quiz.qs.length-1?'See results':'Next question →'}</button>`:`<button class="button-secondary" id="skip-question">Skip for now →</button>`}</div></section>`;}
  function finishQuiz(){if(!quiz)return;if(quiz.clock)clearInterval(quiz.clock);let raw=quiz.correct-(quiz.examMode?quiz.wrong*.25:0),score=Math.max(0,Math.round(raw*100)/100),pct=Math.round(quiz.correct/quiz.qs.length*100);state.results.push({name:quiz.examMode?'Exam mode':`${quiz.kind} practice`,score,total:quiz.qs.length,pct,date:new Date().toISOString(),correct:quiz.correct,wrong:quiz.wrong,topic:quiz.kind});state.totalCorrect=(state.totalCorrect||0)+quiz.correct;state.totalAttempted=(state.totalAttempted||0)+quiz.correct+quiz.wrong;state.answers.push(...quiz.qs.filter(q=>q._correct===true||q._correct===false).map(q=>({id:q.id,topic:q.topic,correct:q._correct,confidence:q._confidence||null,date:new Date().toISOString()})));state.answers=state.answers.slice(-500);save();let result=quiz;quiz={kind:'result',result};render();}
  function resultPage(){let r=quiz.result,weak={};r.qs.forEach(q=>{if(q._correct===false)weak[q.topic]=(weak[q.topic]||0)+1});return `${header('TEST COMPLETE',r.pct>=70?'Nice recall. Keep it warm.':'Good signal. Now you know what to revise.','Your answer record and revision suggestions are saved on this device.')}<section class="quiz-panel result-card"><div class="eyebrow">${r.examMode?'EXAM MODE':'PRACTICE'}</div><div class="result-score">${r.examMode?Math.max(0,Math.round((r.correct-r.wrong*.25)*100)/100):r.correct}<span style="font-size:1.125rem;color:var(--muted)"> / ${r.qs.length}</span></div><h2>${r.pct}% correct</h2><p>${r.correct} correct · ${r.wrong} incorrect · ${r.skipped} skipped${r.examMode?' · −0.25 per wrong':''}</p><div class="result-actions"><button class="button-secondary" data-go="practice">Practice more</button><button class="button-green" id="review-wrongs">Review wrong topics</button></div></section><section class="panel" style="max-width:740px;margin:14px auto"><div class="panel-heading"><h3>Revision suggestions</h3></div>${Object.keys(weak).length?Object.entries(weak).map(([id,n])=>`<div class="weak-row"><div><strong>${esc(topic(id)?.title||id)}</strong><small>${n} question${n>1?'s':''} to revisit</small></div><button class="button-secondary" data-module="${id}">Open lesson →</button></div>`).join(''):`<div class="empty-state"><strong>No wrong answers in this set.</strong>Keep practising to retain the recall.</div>`}</section>`;}
  function revise(){let f=D.flashcards[flashIndex%D.flashcards.length];return `${header('REVISE','Bring the important facts back to mind.','Look at the cue, answer from memory, then flip the card.')}<section class="panel" style="max-width:760px;margin:18px auto"><div class="panel-heading"><h3>Flashcard <span style="color:var(--muted);font-weight:400">${flashIndex+1} / ${D.flashcards.length}</span></h3><button class="text-link" data-module="quick-revision">One-hour revision →</button></div><div class="flashcard" id="flip-card"><div class="flashcard-inner"><small>${flashBack?'ANSWER':'RECALL'}</small><h2>${esc(flashBack?f[1]:f[0])}</h2><p>${flashBack?'Tap to see the cue':'Think of the answer, then tap to flip'}</p></div></div>${flashBack?`<div class="srs-ratings compact"><button data-flash-rating="again">Again <small>${nextIntervalLabel(`flash:${flashIndex}`,'again')}</small></button><button data-flash-rating="hard">Hard <small>${nextIntervalLabel(`flash:${flashIndex}`,'hard')}</small></button><button data-flash-rating="good">Good <small>${nextIntervalLabel(`flash:${flashIndex}`,'good')}</small></button><button data-flash-rating="easy">Easy <small>${nextIntervalLabel(`flash:${flashIndex}`,'easy')}</small></button></div>`:''}<div class="flash-controls"><button class="button-secondary" id="flash-prev">← Previous</button><button class="button-green" id="flash-flip">${flashBack?'Show cue':'Reveal answer'}</button><button class="button-secondary" id="flash-next">Next →</button></div></section><div class="two-col"><section class="panel"><div class="panel-heading"><h3>One-hour Polity revision</h3><button class="text-link" data-module="quick-revision">Open →</button></div><p style="font-size:0.75rem;color:var(--muted);line-height:1.5;margin:0">Articles, rights, duties, Union institutions, courts, emergencies, local government and case anchors in a compact route.</p></section><section class="panel"><div class="panel-heading"><h3>Before exam</h3><button class="text-link" data-module="before-exam">Open →</button></div><p style="font-size:0.75rem;color:var(--muted);line-height:1.5;margin:0">Dates, article anchors, amendments and common traps gathered in one short checklist.</p></section></div>`;}
  function pyqPage(){const exams=['All exams',...new Set(D.pyqs.map(q=>q.exam))],topics=['All topics',...new Set(D.pyqs.map(q=>topic(q.topic)?.title||q.topic))];const rows=D.pyqs.filter(q=>(pyqExamFilter==='All exams'||q.exam===pyqExamFilter)&&(pyqTopicFilter==='All topics'||(topic(q.topic)?.title||q.topic)===pyqTopicFilter));return `${header('PAST-PAPER PRACTICE','Questions tied to real exam papers.','A growing, source-checked archive of selected questions. Each card shows the exam, paper code, date or date limitation, and source.')}<section class="pyq-summary"><div><strong>${D.pyqs.length}</strong><span> sourced questions</span></div><p>Use the filters to find questions by exam or chapter. Tap a card to check the answer.</p></section><div class="pyq-filters"><label>Exam<select id="pyq-exam-filter">${exams.map(x=>`<option ${pyqExamFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Chapter<select id="pyq-topic-filter">${topics.map(x=>`<option ${pyqTopicFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><button class="button-secondary" data-page="sources">How sources are labeled</button></div><div class="pyq-list">${rows.length?rows.map(q=>{const ix=D.pyqs.indexOf(q),isOpen=openPyqs.has(q.id);return `<article class="pyq-card ${isOpen?'open':''}"><div class="pyq-meta"><span class="pyq-exam">${emphasize(q.exam)}</span><span class="pyq-status">${esc(q.status)}</span></div><div class="pyq-paper">${emphasize(q.paper)} <span>·</span> ${emphasize(q.date)}</div><h3>${emphasize(q.q)}</h3><div class="pyq-options">${q.options.map((o,i)=>`<div class="pyq-option ${isOpen&&i===q.answer?'pyq-correct':''}"><span>${String.fromCharCode(65+i)}</span>${emphasize(o)}</div>`).join('')}</div>${isOpen?`<div class="pyq-explanation"><strong>Answer: ${String.fromCharCode(65+q.answer)} · ${emphasize(q.options[q.answer])}</strong><p>${emphasize(q.explanation)}</p></div>`:''}<div class="pyq-footer"><span>${esc(topic(q.topic)?.title||q.topic)}</span><button class="button-secondary" data-pyq-toggle="${q.id}">${isOpen?'Hide answer':'Reveal answer'}</button><a href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">${esc(q.sourceLabel)} ↗</a></div></article>`}).join(''):`<div class="empty-state"><strong>No questions match these filters.</strong>Choose another exam or chapter.</div>`}</div><div class="source-note"><strong>Evidence note:</strong> Kerala PSC entries link to official booklets or answer keys. RRB entries are identified as shift-wise compilations because public candidate response sheets are time-limited. The SSC entry is a candidate response-sheet transcription and is marked as such. This is a sourced, expandable collection; it is not a claim to include every question ever asked.</div>`;}
  function borrowedPage(){return `${header('REFERENCE / MEMORY','Who borrowed what?','Tap a country card to see the features commonly traced to that constitutional model. India adapted these ideas to its own Constitution.')}<section class="borrowed-hero"><div class="borrowed-globe">↗</div><div><strong>Remember the pair, then the feature.</strong><p>Country first. Feature next. A fast recall map for one of the most repeated polity themes.</p></div><span>${D.borrowedFeatures.length} sources</span></section><div class="borrowed-grid">${D.borrowedFeatures.map((c,i)=>{const isOpen=openCountries.has(c.country);return `<button class="borrow-card tone-${c.tone} ${isOpen?'open':''}" data-borrow-toggle="${emphasize(c.country)}"><div class="borrow-top"><span class="borrow-number">${String(i+1).padStart(2,'0')}</span><span class="borrow-open">${isOpen?'−':'+'}</span></div><div class="borrow-country">${emphasize(c.country)}</div><div class="borrow-count">${c.items.length} exam links</div>${isOpen?`<div class="borrow-details"><ul>${c.items.map(x=>`<li>${emphasize(x)}</li>`).join('')}</ul><p>${emphasize(c.note)}</p></div>`:`<div class="borrow-preview">Tap to reveal contributions →</div>`}</button>`}).join('')}</div><div class="trap-box" style="margin-top:16px"><strong>Exam trap:</strong> These are conventional historical attributions, not one-to-one copies. The Constitution of India combines and modifies ideas from several sources. Some standard textbooks differ on a few attributions.</div>`;}
  function progressPage(){let sureAnswers=state.answers.filter(a=>a.confidence==='sure'),calibration=sureAnswers.length?Math.round(sureAnswers.filter(a=>a.correct).length/sureAnswers.length*100):0;let weak=[...new Set(state.answers.filter(a=>!a.correct).map(a=>a.topic))].map(id=>({id,n:state.answers.filter(a=>a.topic===id&&!a.correct).length})).sort((a,b)=>b.n-a.n);let total=state.totalAttempted||0;return `${header('YOUR PROGRESS','A clear view of what’s sticking.','Your study history is stored locally on this device.')}<div class="stat-grid"><div class="stat-card"><div class="stat-top">Curriculum covered</div><div class="stat-value">${progressPct()}%</div><div class="progress-bar-large"><i style="width:${progressPct()}%"></i></div></div><div class="stat-card"><div class="stat-top">Questions attempted</div><div class="stat-value">${total}</div><div class="stat-note">${state.totalCorrect||0} correct responses</div></div><div class="stat-card"><div class="stat-top">Overall accuracy</div><div class="stat-value">${total?Math.round(state.totalCorrect/total*100):0}%</div><div class="stat-note">Across completed practice sets</div></div><div class="stat-card"><div class="stat-top">Study streak</div><div class="stat-value">${currentStreak()}</div><div class="stat-note">All-time days are retained</div></div><div class="stat-card"><div class="stat-top">Sure-answer calibration</div><div class="stat-value">${calibration}%</div><div class="stat-note">${sureAnswers.length} confident answers · ${state.xp||0} recall XP</div></div></div><div class="two-col"><section class="panel"><div class="panel-heading"><h3>Module mastery</h3><button class="text-link" data-go="learn">Continue →</button></div>${D.modules.filter(m=>m.category!=='Revision').map(m=>`<div class="weak-row"><div><strong>${esc(m.title)}</strong><div class="mini-progress" style="margin-top:6px"><i style="width:${state.completed.includes(m.id)?100:0}%"></i></div></div><span class="mastery-badge">${moduleMastery(m)}% mastery</span></div>`).join('')}</section><section class="panel"><div class="panel-heading"><h3>Topics to revisit</h3><button class="text-link" data-go="revise">Flashcards →</button></div>${weak.length?weak.map(x=>`<div class="weak-row"><div><strong>${esc(topic(x.id)?.title||x.id)}</strong><small>${x.n} missed response${x.n>1?'s':''} in saved history</small></div><button class="button-secondary" data-module="${x.id}">Review</button></div>`).join(''):`<div class="empty-state"><strong>No weak topics yet.</strong>Complete a practice set to build your review list.</div>`}${[...new Set(state.misconceptions||[])].slice(-5).map(id=>{const q=[...D.questions,...D.pyqs].find(x=>x.id===id);return q?`<div class="weak-row misconception-row"><div><strong>Confident miss</strong><small>${esc(q.q)} · ${esc(topic(q.topic)?.title||q.topic)}</small><p>${esc(topic(q.topic)?.trap||q.explanation)}</p></div><button class="button-secondary" data-module="${q.topic}">Review</button></div>`:''}).join('')}<div class="source-note">Adaptive revision is intentionally simple: incorrect responses put a topic in this list; repeated correct answers build confidence through your practice history. The study record stays in this browser.</div><div class="export-row"><button class="button-secondary" id="export-data">Export progress JSON</button><button class="button-secondary" id="import-data">Import progress JSON</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><button class="button-secondary" id="reset-data" style="margin-top:14px">Reset all local progress</button></section></div>`;}
  function sourcesPage(){return `${header('CONTENT NOTES','Sources you can check for yourself.','Official references ground the constitutional facts. The syllabus lens is kept separate from PYQ statistics.')}<section class="panel" style="margin-top:17px"><div class="panel-heading"><h3>Official references and PYQ sources</h3><span class="priority high">${D.sources.length} SOURCES</span></div>${D.sources.map((s,i)=>`<div class="source-card"><div class="source-icon">${i===0?'§':i===4?'⚖':'↗'}</div><div><h4>${esc(s.name)} <span style="color:var(--muted);font-weight:400">· ${esc(s.institution)}</span></h4><p>${esc(s.detail)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a></div></div>`).join('')}</section><section class="panel" style="margin-top:14px"><div class="panel-heading"><h3>Research & PYQ method</h3></div><p style="font-size:0.75rem;line-height:1.7;color:var(--muted);margin:0">${esc(D.methodology)}</p><div class="source-note"><strong>What the exam research supports:</strong> RRB NTPC’s official notification explicitly names Indian Polity and Governance—constitution and political system in General Awareness. SSC syllabus information is maintained per examination notification. Kerala PSC publishes post-specific syllabi and question papers; coverage varies. No frequency chart is shown because a verified, representative set of PYQs across exam boards and years was not established here. The question bank in this app is original practice content.</div><div class="source-note"><strong>Change-sensitive topics:</strong> Use the current official notification and Constitution text for exam-year rules. The Constitution source linked above is the Government of India 2024 edition incorporating amendments through the 106th Amendment Act, 2023.</div></section>`;}
  let lastRenderedPage=null;
  let trapClock=null,timelineGame=null,countryGame=null,articlePick=null,amendmentPick=null,articleRevealed=false,timelineFocus=0;
  function startTrapDuel(moduleId){const chosen=topic(moduleId),mods=D.modules.filter(m=>m.trap&&m.summary).sort(()=>Math.random()-.5).slice(0,5);if(chosen&&chosen.trap)mods[0]=chosen;trapDuel={items:mods.map(m=>({title:m.title,trap:m.trap,other:m.summary,options:Math.random()<.5?[m.trap,m.summary]:[m.summary,m.trap]})),index:0,score:0,seconds:30};currentPage='trap';$('#page-label').textContent='Trap Duel';render();clearInterval(trapClock);trapClock=setInterval(()=>{if(!trapDuel)return;trapDuel.seconds--;const timer=$('#trap-clock');if(timer)timer.textContent=trapDuel.seconds+'s';if(trapDuel.seconds<=0){clearInterval(trapClock);trapDuel.index=trapDuel.items.length;render()}},1000);}
  function trapPage(){if(!trapDuel)return `${header('TRAP DUEL','Time is up.','Start another quick round from any lesson.') }<section class="quiz-panel"><div class="result-score">${trapDuel?.score||0}<span> / 5</span></div><button class="button-green" data-go="learn">Back to lessons</button></section>`;if(trapDuel.index>=trapDuel.items.length){clearInterval(trapClock);return `${header('TRAP DUEL COMPLETE','Fast distinctions, better recall.','You spotted '+trapDuel.score+' of 5 common exam traps.') }<section class="quiz-panel"><div class="result-score">${trapDuel.score}<span> / 5</span></div><button class="button-green" data-go="learn">Choose another lesson</button></section>`;}const x=trapDuel.items[trapDuel.index];return `${header('TRAP DUEL','Which line is the common exam trap?','Choose the warning for '+esc(x.title)+'.')}<section class="quiz-panel"><div class="quiz-top"><span>Round ${trapDuel.index+1} of 5</span><strong id="trap-clock">${trapDuel.seconds}s</strong></div><div class="option-list">${x.options.map((o,i)=>`<button class="option" data-trap-answer="${i}">${esc(o)}</button>`).join('')}</div><p>Score ${trapDuel.score} · Timer runs for the full round.</p></section>`;}
  function moduleMastery(m){const facts=(m.facts||[]).map((_,i)=>window.POLITY_SRS.record(state,`fact:${m.id}:${i}`)),recalls=facts.length?facts.reduce((n,r)=>n+(r.reps>=2?1:r.reps?0.5:0),0)/facts.length:0,ans=state.answers.filter(a=>a.topic===m.id),accuracy=ans.length?ans.filter(a=>a.correct).length/ans.length:0;return Math.round(Math.min(100,(state.completed.includes(m.id)?35:0)+recalls*45+accuracy*20));}
  function mapPage(){const nodes=D.modules.filter(m=>m.category!=='Revision'),cols=4,gapX=235,gapY=125,width=cols*gapX+30,height=Math.ceil(nodes.length/cols)*gapY+40,coords=nodes.map((m,i)=>({m,x:30+(i%cols)*gapX+82,y:40+Math.floor(i/cols)*gapY+35}));return `${header('SEE THE WHOLE SYSTEM','Your polity knowledge map.','Each node reflects lessons completed, spaced recall and question results. Select a topic to open its lesson.')}<section class="panel"><div class="panel-heading"><h3>${nodes.length} connected modules</h3><span class="priority high">${state.xp||0} RECALL XP</span></div><svg class="knowledge-map" viewBox="0 0 ${width} ${height}" role="img" aria-label="Connected map of polity modules">${coords.slice(0,-1).map((p,i)=>`<line x1="${p.x}" y1="${p.y}" x2="${coords[i+1].x}" y2="${coords[i+1].y}" stroke="var(--line)" stroke-width="3"/>`).join('')}${coords.map(({m,x,y})=>`<g class="map-node" data-module="${m.id}" tabindex="0" role="button" aria-label="${esc(m.title)} ${moduleMastery(m)} percent mastery"><circle cx="${x}" cy="${y}" r="34" fill="${moduleMastery(m)>=70?'#397656':moduleMastery(m)>=35?'#8aa98c':'#dce4dc'}"/><text x="${x}" y="${y+52}" text-anchor="middle">${esc(m.title.length>22?m.title.slice(0,20)+'…':m.title)}</text><text x="${x}" y="${y+5}" text-anchor="middle" fill="white">${moduleMastery(m)}%</text></g>`).join('')}</svg><div class="game-row"><button class="button-secondary" id="start-timeline">Timeline order game</button><button class="button-secondary" id="start-country-game">Country match game</button><button class="button-secondary" data-go="games">Article explorer & amendments</button></div></section>`;}
  function plannerPage(){const p=state.planner||{},examDate=p.date||'',exam=p.exam||'RRB';const today=new Date();const daysLeft=examDate?Math.max(0,Math.ceil((new Date(examDate+'T00:00:00')-today)/86400000)):0;const weak=Object.entries(state.answers.reduce((a,x)=>{if(!x.correct)a[x.topic]=(a[x.topic]||0)+1;return a},{})).sort((a,b)=>b[1]-a[1]).map(x=>x[0]);const prioritized=[...D.modules.filter(m=>m.category!=='Revision')].sort((a,b)=>((weak.indexOf(b.id)>=0?weak.length-weak.indexOf(b.id):0)+(b.priority==='very-high'?3:b.priority==='high'?2:0))-((weak.indexOf(a.id)>=0?weak.length-weak.indexOf(a.id):0)+(a.priority==='very-high'?3:a.priority==='high'?2:0)));const slots=Math.max(1,Math.min(daysLeft||7,365));return `${header('PLAN YOUR REVISION','A simple path to exam day.','Pick your exam date and track. The plan gives more space to topics you have missed and foundational modules.')}<section class="panel"><form id="planner-form" class="planner-form"><label>Exam date<input type="date" id="planner-date" value="${esc(examDate)}" required min="${dateKey(today)}"></label><label>Track<select id="planner-exam"><option ${exam==='RRB'?'selected':''}>RRB</option><option ${exam==='SSC'?'selected':''}>SSC</option></select></label><button class="button-green">Build my plan</button></form>${examDate?`<p style="margin:14px 0 0">${daysLeft} days until your ${esc(exam)} exam.</p>`:''}</section>${examDate?`<section class="panel" style="margin-top:16px"><div class="panel-heading"><h3>Suggested daily route</h3><span class="priority high">WEAK TOPICS FIRST</span></div>${Array.from({length:slots},(_,i)=>{const m=prioritized[i%prioritized.length];return `<div class="weak-row"><div><strong>Day ${i+1} · ${esc(m.title)}</strong><small>Review lesson · due recall · 10-question focused sprint</small></div><button class="button-secondary" data-module="${m.id}">Open</button></div>`}).join('')}</section>`:''}<section class="panel" style="margin-top:16px"><div class="panel-heading"><h3>Mock exam settings</h3><span>Negative marking · 0.25 per wrong answer</span></div><button class="button-green" data-quiz-exam="weighted">Start weakness-weighted mock</button></section>`;}
  function articleItems(){const out=[];D.modules.forEach(m=>(m.facts||[]).forEach(([label,body],i)=>{const text=label+' '+body;for(const match of text.matchAll(/Articles?\s+(\d+[A-Z]?(?:\s*(?:and|to|,|&|–|-)\s*\d+[A-Z]?)*)/gi))out.push({article:match[1],topic:m.title,text,source:`${label}: ${body}`,key:`fact:${m.id}:${i}`})}));return [...new Map(out.map(x=>[x.article,x])).values()].slice(0,80);}
  function moveTimeline(delta){if(!timelineGame)return;const to=Math.max(0,Math.min(timelineGame.items.length-1,timelineFocus+delta));if(to===timelineFocus)return;[timelineGame.items[timelineFocus],timelineGame.items[to]]=[timelineGame.items[to],timelineGame.items[timelineFocus]];timelineFocus=to;timelineGame.checked=false;render()}
  function startTimeline(){timelineFocus=0;const m=D.modules.filter(x=>(x.timeline||[]).length>=4).sort(()=>Math.random()-.5)[0];if(!m)return;timelineGame={module:m,items:m.timeline.map((x,i)=>({date:x[0],text:x[1],order:i})).sort(()=>Math.random()-.5),checked:false};currentPage='games';$('#page-label').textContent='Active recall games';render();}
  function gamesPage(){const items=articleItems();const m=D.modules.find(x=>x.id==='amendments');return `${header('ACTIVE RECALL GAMES','Make the links stick.','Short interactive rounds for dates, Articles, borrowed features and amendments.')}<section class="panel"><div class="panel-heading"><h3>Timeline · put the events in order</h3><button class="button-green" id="start-timeline">New round</button></div>${timelineGame?`<p>${esc(timelineGame.module.title)} · move events with the arrows, then check.</p>${timelineGame.items.map((x,i)=>`<div class="weak-row" data-index="${i}"><div><strong>${esc(x.date)}</strong><small>${esc(x.text)}</small></div><span><button class="button-secondary" data-timeline-move="${i-1}" ${i===0?'disabled':''}>↑</button><button class="button-secondary" data-timeline-move="${i+1}" ${i===timelineGame.items.length-1?'disabled':''}>↓</button></span></div>`).join('')}<button class="button-green" id="check-timeline">Check order</button>${timelineGame.checked?`<p>${timelineGame.items.every((x,i)=>x.order===i)?'Correct order. +20 recall XP':'Not quite yet. Review the lesson timeline and try another round.'}</p>`:''}`:`<p>Use the arrows to arrange a chapter timeline in chronological order.</p>`}</section><section class="panel" style="margin-top:16px"><div class="panel-heading"><h3>Article explorer</h3><span>${items.length} recall prompts</span></div><div class="filter-row">${items.slice(0,30).map((x,i)=>`<button class="filter-chip ${articlePick===i?'selected':''}" data-article-pick="${i}">Article ${esc(x.article)}</button>`).join('')}</div>${articlePick!==null&&items[articlePick]?`<div class="answer-note"><strong>Recall: Article ${esc(items[articlePick].article)}</strong><p>${articleRevealed?`${esc(items[articlePick].topic)} · ${esc(items[articlePick].source)}`:'Try to recall the provision’s subject before revealing the context.'}</p>${articleRevealed?`<div class="srs-ratings compact">${['again','hard','good','easy'].map(r=>`<button data-article-rating="${r}" data-article-key="${esc(items[articlePick].key)}">${r}<small>${nextIntervalLabel(items[articlePick].key,r)}</small></button>`).join('')}</div>`:`<button class="button-secondary" id="article-reveal">Reveal context</button>`}</div>`:''}</section><section class="panel" style="margin-top:16px"><div class="panel-heading"><h3>Amendment card stack</h3><span>${(m?.facts||[]).length} cards</span></div>${(m?.facts||[]).slice(0,8).map(([a,b],i)=>`<details class="amendment-card"><summary>${emphasize(a)}</summary><p>${emphasize(b)}</p><div class="srs-ratings compact">${['again','hard','good','easy'].map(v=>`<button data-amendment-rating="${v}" data-amendment-key="${i}">${v}<small>${nextIntervalLabel(`fact:amendments:${i}`,v)}</small></button>`).join('')}</div></details>`).join('')}</section>`;}
  function startCountryGame(){countryGame={round:0,score:0,pairs:[...D.borrowedFeatures].sort(()=>Math.random()-.5).slice(0,5),selected:null};currentPage='country-game';$('#page-label').textContent='Country match';render();}
  function countryGamePage(){if(!countryGame)return gamesPage();if(countryGame.round>=countryGame.pairs.length)return `${header('COUNTRY MATCH','Round complete.','You matched '+countryGame.score+' of 5 country-feature pairs.') }<section class="panel"><button class="button-green" id="start-country-game">Play again</button><button class="button-secondary" data-go="map">Knowledge map</button></section>`;const pair=countryGame.pairs[countryGame.round],features=[pair.items[0],...D.borrowedFeatures.filter(x=>x.country!==pair.country).map(x=>x.items[0]).sort(()=>Math.random()-.5).slice(0,3)];return `${header('COUNTRY MATCH','Match '+esc(pair.country)+' to a feature.','Drag the country label onto its match, or tap the matching feature.')}<section class="quiz-panel"><div class="country-token" draggable="true" data-country-token="${esc(pair.country)}" aria-label="Drag ${esc(pair.country)} to a feature">${esc(pair.country)} <small>Drag this label</small></div><div class="option-list">${features.map((x,i)=>`<button class="option feature-drop" data-country-answer="${i}" data-feature-drop="true" data-correct-country="${x===pair.items[0]}">${esc(x)}</button>`).join('')}</div><p>Pair ${countryGame.round+1} of 5 · Score ${countryGame.score}</p></section>`;}
  function awardXP(points){state.xp=(state.xp||0)+points;const day=dateKey(new Date());state.xpByDay||={};state.xpByDay[day]=(state.xpByDay[day]||0)+points;}
  function render(){const same=lastRenderedPage===currentPage,oldY=window.scrollY,active=document.activeElement,focusId=same&&active&&['INPUT','TEXTAREA','SELECT'].includes(active.tagName)?active.id:null,focusAttr=same&&active?.dataset?['option','confidence','sprintOption','srsRate','revealFact','lessonMode','filter','countryAnswer','articlePick','timelineMove'].find(k=>active.dataset[k]!==undefined):null,selection=focusId&&active.selectionStart!==undefined?[active.selectionStart,active.selectionEnd]:null;renderSide();const c=$('#page-content'),oldQuizPanel=same&&currentPage==='quiz'&&quiz?.kind!=='result'?c.querySelector('.quiz-panel'):null;if(currentPage==='dashboard')c.innerHTML=dashboard();else if(currentPage==='learn')c.innerHTML=learn();else if(currentPage==='lesson')c.innerHTML=modulePage(topic(currentModule));else if(currentPage==='practice')c.innerHTML=practice();else if(currentPage==='pyqs')c.innerHTML=pyqPage();else if(currentPage==='borrowed')c.innerHTML=borrowedPage();else if(currentPage==='quiz'){const html=quiz?.kind==='result'?resultPage():quizPage();if(oldQuizPanel&&quiz?.kind!=='result'){const temp=document.createElement('div');temp.innerHTML=html;const nextPanel=temp.querySelector('.quiz-panel');if(nextPanel)oldQuizPanel.replaceWith(nextPanel);else c.innerHTML=html}else c.innerHTML=html;}else if(currentPage==='sprint')c.innerHTML=sprintPage();else if(currentPage==='country-game')c.innerHTML=countryGamePage();else if(currentPage==='map')c.innerHTML=mapPage();else if(currentPage==='planner')c.innerHTML=plannerPage();else if(currentPage==='trap')c.innerHTML=trapPage();else if(currentPage==='games')c.innerHTML=gamesPage();else if(currentPage==='revise')c.innerHTML=revise();else if(currentPage==='progress')c.innerHTML=progressPage();else if(currentPage==='sources')c.innerHTML=sourcesPage();else c.innerHTML=dashboard();lastRenderedPage=currentPage;if(same){if(focusId){const next=$('#'+focusId);next?.focus({preventScroll:true});if(selection)next.setSelectionRange(...selection)}else if(focusAttr){const next=$(`[data-${focusAttr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}="${active.dataset[focusAttr]}"]`);if(next&&!next.disabled)next.focus({preventScroll:true})}window.scrollTo(0,oldY)}}
  function openModule(id){let m=topic(id);if(!m)return;currentModule=id;state.lastModule=id;currentPage='lesson';quiz=null;$('#page-label').textContent='Learn';$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page==='learn'));markStudy();render();window.scrollTo({top:0,behavior:'smooth'});}
  function answer(i){if(!quiz||quiz.answered)return;const q=quiz.qs[quiz.index];quiz.selected=i;quiz.answered=true;quiz.confidence=null;q._correct=i===q.answer;if(q._correct)quiz.correct++;else quiz.wrong++;markStudy();render();}
  function submitConfidence(level){if(!quiz||!quiz.answered)return;const q=quiz.qs[quiz.index];quiz.confidence=level;q._confidence=level;if(q._correct){window.POLITY_SRS.schedule(state,`question:${q.id}`,level==='sure'?'good':'hard');awardXP(level==='guess'?5:10)}else{window.POLITY_SRS.schedule(state,`question:${q.id}`,'again');if(level==='sure')state.misconceptions=[...(state.misconceptions||[]),q.id]}save();render();}
  function nextQuestion(){if(!quiz)return;if(quiz.answered&&!quiz.confidence)return;if(quiz.index>=quiz.qs.length-1){finishQuiz();return}quiz.index++;quiz.answered=false;quiz.selected=null;quiz.confidence=null;render();}
  function flip(delta=0){if(delta===0)flashBack=!flashBack;else{flashIndex=(flashIndex+delta+D.flashcards.length)%D.flashcards.length;flashBack=false}render();}
  function renderSearch(q=''){let box=$('#search-results'),term=q.trim().toLowerCase();if(!term){box.innerHTML='<div class="search-hint">Search lessons, articles, amendments and revision facts.</div>';return}let hits=[];D.modules.forEach(m=>{let hay=[m.title,m.summary,m.remember,m.trap,...(m.facts||[]).flat()].join(' ').toLowerCase();if(hay.includes(term))hits.push({title:m.title,desc:`${m.category} · ${m.summary}`,action:()=>openModule(m.id)})});D.flashcards.forEach(f=>{if(f.join(' ').toLowerCase().includes(term))hits.push({title:f[0],desc:f[1],action:()=>{go('revise');let i=D.flashcards.indexOf(f);flashIndex=i;flashBack=true;render()}})});D.questions.forEach(x=>{if((x.q+x.explanation+x.options.join(' ')).toLowerCase().includes(term))hits.push({title:x.q,desc:`${topic(x.topic)?.title||x.topic} · practice question`,action:()=>{startQuiz('topic')}})});D.pyqs.forEach(x=>{if((x.q+x.exam+x.paper+x.explanation+x.options.join(' ')).toLowerCase().includes(term))hits.push({title:x.q,desc:`${x.exam} · ${x.paper}`,action:()=>go('pyqs')})});box.innerHTML=hits.length?hits.slice(0,12).map((h,i)=>`<button class="search-result" data-search-hit="${i}"><strong>${esc(h.title)}</strong><small>${esc(h.desc)}</small></button>`).join(''):`<div class="search-empty">No results for “${esc(q)}”. Try an article, institution, case or topic name.</div>`;box._hits=hits;}
  function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2100)}
  document.addEventListener('change',e=>{if(e.target.dataset.mnemonic){state.mnemonics[e.target.dataset.mnemonic]=e.target.value;save();return}if(e.target.id==='pyq-exam-filter'){pyqExamFilter=e.target.value;render();return}if(e.target.id==='pyq-topic-filter'){pyqTopicFilter=e.target.value;render();return}});
  document.addEventListener('dragstart',e=>{const token=e.target.closest('[data-country-token]');if(token)e.dataTransfer.setData('text/plain',token.dataset.countryToken)});document.addEventListener('dragover',e=>{if(e.target.closest('[data-feature-drop]'))e.preventDefault()});document.addEventListener('drop',e=>{const target=e.target.closest('[data-feature-drop]');if(!target||!countryGame)return;e.preventDefault();const expected=countryGame.pairs[countryGame.round]?.country;if(e.dataTransfer.getData('text/plain')===expected){if(target.dataset.correctCountry==='true'){countryGame.score++;awardXP(4)}countryGame.round++;save();render()}else showToast('That country does not match this feature. Try again.');});document.addEventListener('submit',e=>{if(e.target.id==='planner-form'){e.preventDefault();state.planner={date:$('#planner-date').value,exam:$('#planner-exam').value};save();render();showToast('Your study plan is ready')}});
  document.addEventListener('click',e=>{
    const flashRating=e.target.closest('[data-flash-rating]');if(flashRating){window.POLITY_SRS.schedule(state,`flash:${flashIndex}`,flashRating.dataset.flashRating);if(flashRating.dataset.flashRating!=='again')awardXP(5);save();flip(1);return}const modeBtn=e.target.closest('[data-lesson-mode]');if(modeBtn){lessonMode=modeBtn.dataset.lessonMode;render();return}const clozeToggle=e.target.closest('[data-cloze-toggle]');if(clozeToggle){const k=clozeToggle.dataset.clozeToggle;clozeFacts.has(k)?clozeFacts.delete(k):clozeFacts.add(k);render();return}const clozeAnswer=e.target.closest('[data-cloze-answer]');if(clozeAnswer){clozeAnswer.textContent=clozeAnswer.dataset.clozeAnswer;clozeAnswer.classList.add('revealed');return}const revealFact=e.target.closest('[data-reveal-fact]');if(revealFact){revealedFacts.add(revealFact.dataset.revealFact);render();return}const rateFact=e.target.closest('[data-rate-fact]');if(rateFact){window.POLITY_SRS.schedule(state,rateFact.dataset.rateFact,rateFact.dataset.rating);if(rateFact.dataset.rating!=='again')awardXP(5);save();showToast('Review scheduled · '+rateFact.dataset.rating);return}const duel=e.target.closest('[data-trap-duel]');if(duel){startTrapDuel(duel.dataset.trapDuel);return}const trapAnswer=e.target.closest('[data-trap-answer]');if(trapAnswer&&trapDuel){const x=trapDuel.items[trapDuel.index];if(x.options[Number(trapAnswer.dataset.trapAnswer)]===x.trap){trapDuel.score++;awardXP(4);}trapDuel.index++;render();return}const countryAnswer=e.target.closest('[data-country-answer]');if(countryAnswer&&countryGame){if(countryAnswer.dataset.correctCountry==='true'){countryGame.score++;awardXP(4)}countryGame.round++;save();render();return}const timelineMove=e.target.closest('[data-timeline-move]');if(timelineMove&&timelineGame){const i=Number(timelineMove.dataset.timelineMove),j=Number(timelineMove.parentElement.parentElement.dataset.index||i);if(i>=0&&i<timelineGame.items.length){const row=timelineMove.closest('.weak-row');const current=Number(row.dataset.index);const to=Number(timelineMove.dataset.timelineMove);[timelineGame.items[current],timelineGame.items[to]]=[timelineGame.items[to],timelineGame.items[current]];render()}return}const pyqToggle=e.target.closest('[data-pyq-toggle]');if(pyqToggle){const id=pyqToggle.dataset.pyqToggle;openPyqs.has(id)?openPyqs.delete(id):openPyqs.add(id);render();return}
    const borrowToggle=e.target.closest('[data-borrow-toggle]');if(borrowToggle){const country=borrowToggle.dataset.borrowToggle;openCountries.has(country)?openCountries.delete(country):openCountries.add(country);render();return}
    const nav=e.target.closest('[data-page]');if(nav){go(nav.dataset.page);return}
    const goBtn=e.target.closest('[data-go]');if(goBtn){go(goBtn.dataset.go);return}
    const mod=e.target.closest('[data-module]');if(mod){openModule(mod.dataset.module);return}
    const fil=e.target.closest('[data-filter]');if(fil){filter=fil.dataset.filter;render();return}
    const chapter=e.target.closest('[data-chapter-test]');if(chapter){startQuiz('chapter-check',false,chapter.dataset.chapterTest);return}
    const qbtn=e.target.closest('[data-quiz]');if(qbtn){startQuiz(qbtn.dataset.quiz,false);return}
    const conf=e.target.closest('[data-confidence]');if(conf){submitConfidence(conf.dataset.confidence);return}const opt=e.target.closest('[data-option]');if(opt){answer(Number(opt.dataset.option));return}
    const article=e.target.closest('[data-article-pick]');if(article){articlePick=Number(article.dataset.articlePick);articleRevealed=false;render();return}const articleRate=e.target.closest('[data-article-rating]');if(articleRate){window.POLITY_SRS.schedule(state,articleRate.dataset.articleKey,articleRate.dataset.articleRating);if(articleRate.dataset.articleRating!=='again')awardXP(5);save();showToast('Article recall scheduled');return}const amend=e.target.closest('[data-amendment-rating]');if(amend){window.POLITY_SRS.schedule(state,`fact:amendments:${amend.dataset.amendmentKey}`,amend.dataset.amendmentRating);if(amend.dataset.amendmentRating!=='again')awardXP(5);save();showToast('Amendment card scheduled');return}const hit=e.target.closest('[data-search-hit]');if(hit){const h=$('#search-results')._hits?.[Number(hit.dataset.searchHit)];if(h){closeSearch();h.action()}return}
    if(e.target.id==='start-sprint'){startSprint();return}if(e.target.id==='start-timeline'){startTimeline();return}if(e.target.id==='start-country-game'){startCountryGame();return}if(e.target.id==='check-timeline'&&timelineGame){timelineGame.checked=true;const ok=timelineGame.items.every((x,i)=>x.order===i);if(ok)awardXP(20);save();render();return}if(e.target.id==='article-reveal'){articleRevealed=true;render();return}if(e.target.id==='sprint-reveal'){sprintRevealed=true;render();return}const sprintOption=e.target.closest('[data-sprint-option]');if(sprintOption){sprintChoice=Number(sprintOption.dataset.sprintOption);if(sprintItems[sprintIndex]?.kind==='question'&&sprintChoice!==sprintItems[sprintIndex].question.answer)state.misconceptions=[...(state.misconceptions||[]),sprintItems[sprintIndex].question.id];render();return}const srsRate=e.target.closest('[data-srs-rate]');if(srsRate){rateSprint(srsRate.dataset.srsRate);return}if(e.target.id==='mark-complete'){let m=topic(currentModule);if(m&&!state.completed.includes(m.id))state.completed.push(m.id);markStudy();if(m?.category==='Revision')showToast('Revision page marked complete.');else{let list=D.modules.filter(x=>x.category!=='Revision'),i=list.findIndex(x=>x.id===m.id),next=list[i+1];if(next){openModule(next.id);showToast('Lesson saved. Next up: '+next.title)}else{render();showToast('Lesson saved.')}}return}
    if(e.target.id==='bookmark'){let i=state.bookmarks.indexOf(currentModule);if(i>=0)state.bookmarks.splice(i,1);else state.bookmarks.push(currentModule);save();render();showToast(i>=0?'Removed from saved lessons':'Lesson saved for revision');return}
    if(e.target.id==='quiz-next'){nextQuestion();return}if(e.target.id==='skip-question'){quiz.skipped++;if(quiz.index>=quiz.qs.length-1)finishQuiz();else{quiz.index++;quiz.answered=false;quiz.selected=null;quiz.confidence=null;render()}return}
    if(e.target.id==='flip-card'||e.target.id==='flash-flip'){flip();return}if(e.target.id==='flash-next'){flip(1);return}if(e.target.id==='flash-prev'){flip(-1);return}
    if(e.target.id==='review-wrongs'){go('progress');return}
    if(e.target.closest('[data-speak-lesson]')){if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance($('.lesson-body')?.innerText||''))}else showToast('Read aloud is not supported in this browser');return}if(e.target.id==='theme-toggle'){state.theme=state.theme==='dark'?'light':'dark';save();renderSide();return}
    if(e.target.id==='search-open'){openSearch();return}if(e.target.id==='search-close'){closeSearch();return}
    if(e.target.id==='mobile-menu'){$('#sidebar').classList.toggle('open');return}
    if(e.target.id==='export-data'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='polity-prep-progress.json';a.click();URL.revokeObjectURL(url);return}if(e.target.id==='import-data'){$('#import-file').click();return}if(e.target.id==='reset-data'){if(confirm('Clear all saved study progress, answers, and results from this device?')){localStorage.removeItem(storeKey);localStorage.removeItem(legacyKey);location.reload()}return}
    if(e.target.id==='search-modal'&&e.target.classList.contains('open'))closeSearch();
  });
  document.addEventListener('selectionchange',()=>{const text=window.getSelection()?.toString().trim();let button=$('#make-selection-card');if(text&&$('.lesson-body')?.contains(window.getSelection()?.anchorNode)){if(!button){button=document.createElement('button');button.id='make-selection-card';button.className='button-green';button.textContent='Make my card';button.addEventListener('click',()=>{const front=prompt('Write a short recall cue for the selected text:');if(!front)return;state.personalCards.push({id:'personal-'+Date.now(),front,back:window.getSelection()?.toString().trim()||'',createdAt:Date.now()});save();showToast('Personal card added to your review queue');button.remove()});document.body.append(button)}}else button?.remove()});
  function openSearch(){$('#search-modal').classList.add('open');$('#search-modal').setAttribute('aria-hidden','false');$('#search-input').value='';renderSearch();setTimeout(()=>$('#search-input').focus(),50)}
  function closeSearch(){$('#search-modal').classList.remove('open');$('#search-modal').setAttribute('aria-hidden','true')}
  document.addEventListener('change',e=>{if(e.target.id!=='import-file')return;const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!imported||!Array.isArray(imported.completed)||typeof imported!=='object')throw Error('Invalid progress file');if(!confirm('Replace this browser’s current progress with the imported backup?'))return;state={...initial,...imported};save();render();showToast('Progress restored')}catch{showToast('That file is not a valid Polity Prep backup')}};reader.readAsText(file)});$('#text-larger').addEventListener('click',()=>{state.fontScale=Math.min(1.2,(state.fontScale||1)+.05);save();renderSide()});$('#text-smaller').addEventListener('click',()=>{state.fontScale=Math.max(1,(state.fontScale||1)-.05);save();renderSide()});$('#search-input').addEventListener('input',e=>renderSearch(e.target.value));
  document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='/'&&!e.metaKey&&!e.ctrlKey){e.preventDefault();openSearch()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape')closeSearch();if((e.key==='+'||e.key==='=')&&(e.ctrlKey||e.metaKey)){e.preventDefault();state.fontScale=Math.min(1.2,(state.fontScale||1)+.05);save();renderSide();}if((e.key==='-'||e.key==='_')&&(e.ctrlKey||e.metaKey)){e.preventDefault();state.fontScale=Math.max(.9,(state.fontScale||1)-.05);save();renderSide();}if(currentPage==='quiz'&&!quiz?.answered&&/^[1-4]$/.test(e.key)){const opts=$('[data-option]');if(opts[Number(e.key)-1])answer(Number(e.key)-1)}if(currentPage==='sprint'&&/^[1-4]$/.test(e.key)){const ratings=['again','hard','good','easy'];if(sprintItems[sprintIndex]?.kind==='question'?sprintChoice!==null:sprintRevealed)rateSprint(ratings[Number(e.key)-1])}if(currentPage==='sprint'&&e.key.toLowerCase()==='j'){sprintIndex=Math.max(0,sprintIndex-1);sprintChoice=null;sprintRevealed=false;render()}if(currentPage==='sprint'&&e.key.toLowerCase()==='k'){sprintIndex=Math.min(sprintItems.length-1,sprintIndex+1);sprintChoice=null;sprintRevealed=false;render()}if(currentPage==='games'&&e.key.toLowerCase()==='j'&&timelineGame)moveTimeline(-1);if(currentPage==='games'&&e.key.toLowerCase()==='k'&&timelineGame)moveTimeline(1);if(currentPage==='revise'&&e.code==='Space'){e.preventDefault();flip()}if(currentPage==='revise'&&e.key.toLowerCase()==='j')flip(-1);if(currentPage==='revise'&&e.key.toLowerCase()==='k')flip(1);if(currentPage==='revise'&&flashBack&&/^[1-4]$/.test(e.key)){const rates=['again','hard','good','easy'];window.POLITY_SRS.schedule(state,`flash:${flashIndex}`,rates[Number(e.key)-1]);if(rates[Number(e.key)-1]!=='again')awardXP(5);save();flip(1)}if(currentPage==='sprint'&&e.code==='Space'){e.preventDefault();sprintRevealed=true;render();}if(currentPage==='quiz'&&quiz?.answered&&e.key==='Enter')nextQuestion()});
  $('#search-open').addEventListener('click',openSearch);$('#search-close').addEventListener('click',closeSearch);
  // Exam mode and quick test entry from the dashboard.
  document.addEventListener('click',e=>{const q=e.target.closest('[data-quiz-exam]');if(q)startQuiz(q.dataset.quizExam,true);});
  render();
})();
